package edu.brook;

/**
 * Demographic Prisoner_s Dilemma Java Implementation.
 * 
 * Generated by metaabm system: Dec 11, 2009 6:59:52 PM PST in project: org.eclipse.amp.amf.examples.escape  */
public class DemographicPrisonersDilemma3D extends DemographicPrisonersDilemma
		implements
			org.eclipse.amp.agf3d.I3DModelFactoryProvider {
	public void createGraphicViews() {
		addView(new org.eclipse.amp.escape.ascape.agf3d.GEF3DView());
	}

	public org.eclipse.gef.EditPartFactory getEditPart3DFactory() {
		return new org.eclipse.amp.escape.ascape.adapt.Ascape3DPartFactory() {
			public org.eclipse.jface.viewers.IColorProvider getColorProvider(
					Object model) {

				if (model instanceof Player) {
					return new edu.brook.CooperateDefectStyleColorProvider();
				}

				if (model instanceof PlayCell) {
					return new edu.brook.PlayCellStyleColorProvider();
				}

				return null;
			}
		};
	}

}
